/**
 * MCP command handler
 */
import { defineSchema, lazySchema } from "../../../src/schemas/index.js";
import { onSignal as registerSignalHandler } from "../../../src/platform/compat/process/lifecycle.js";
import { createArgParser, parseArgsOrThrow } from "../../shared/args.js";
const getMCPArgsSchema = defineSchema((v) => v.object({
    port: v.number().optional(),
}));
const MCPArgsSchema = lazySchema(getMCPArgsSchema);
export const parseMCPArgs = createArgParser(MCPArgsSchema, {
    port: { keys: ["port"], type: "number" },
});
export async function handleMCPCommand(args) {
    const data = parseArgsOrThrow(parseMCPArgs, "MCP", args);
    const { createStandaloneMCPServer } = await import("../../mcp/standalone.js");
    const mcpServer = createStandaloneMCPServer({ port: data.port });
    // Keep process alive until interrupted, then shut down gracefully
    const { promise, resolve } = Promise.withResolvers();
    const shutdown = () => {
        mcpServer.stop();
        resolve();
    };
    registerSignalHandler("SIGINT", shutdown);
    registerSignalHandler("SIGTERM", shutdown);
    await promise;
}
